# =============================================================================
# Brazil (BRA) - currency basket regimes
# Generated by the EMDE website build on 2026-10-30. Self-contained: needs only
# BRA_fx_data.csv (in the same folder) and the packages below.
# Rates in the CSV are expressed in units of NZD.
# =============================================================================

for (p in c("zoo", "fxregime")) {
  if (!requireNamespace(p, quietly = TRUE)) install.packages(p, repos = "https://cloud.r-project.org")
}
library(zoo)
library(fxregime)

# ---- model code (identical for every country) -------------------------------
# ---------------------------------------------------------------------------
# fit.R : the statistical core. Base R + zoo + fxregime only.
# This file is sourced by build.R AND pasted verbatim into every country's
# downloadable script, so it must not depend on anything else in the project.
# ---------------------------------------------------------------------------

# fx          data.frame with a `date` column and one column per currency, each
#             expressed in units of the numeraire currency (columns: ccy, USD, regressors)
# ccy         name of the column being explained
# regressors  currencies on the right-hand side (ccy itself is dropped)
fit_country <- function(fx, ccy, regressors = c("USD", "JPY", "EUR", "GBP"),
                        h = 26, breaks = 10, ic = "BIC", frequency = "weekly") {
  regs <- setdiff(regressors, ccy)
  cols <- unique(c(ccy, "USD", regs))
  fx <- fx[stats::complete.cases(fx[, c("date", cols)]), , drop = FALSE]
  fx$date <- as.Date(fx$date)

  # Levels vs USD (for the level plot)
  level <- data.frame(date = fx$date, rate = fx[[ccy]] / fx$USD)

  fx_zoo <- zoo::zoo(as.matrix(fx[, cols, drop = FALSE]), order.by = fx$date)
  ret <- fxregime::fxreturns(
    ccy, frequency = frequency,
    start = min(fx$date), end = max(fx$date),
    other = regs, data = fx_zoo
  )
  dates <- zoo::index(ret)
  d     <- as.data.frame(zoo::coredata(ret))
  n     <- nrow(d)
  frm   <- stats::as.formula(paste(ccy, "~", paste(regs, collapse = " + ")))

  note <- ""
  reg <- tryCatch(
    fxregime::fxregimes(frm, data = ret, h = h, breaks = breaks, hpc = "none", ic = ic),
    error = function(e) {
      note <<- paste("fxregimes failed, single regime used:", conditionMessage(e))
      NULL
    }
  )

  bp <- if (is.null(reg)) integer(0) else reg$breakpoints
  bp <- bp[!is.na(bp)]
  ends   <- c(bp, n)
  starts <- c(1L, bp + 1L)
  k      <- length(ends)

  # R-squared of each regime from a plain lm on that segment
  fits <- lapply(seq_len(k), function(i) {
    suppressWarnings(stats::lm(frm, data = d[starts[i]:ends[i], , drop = FALSE]))
  })
  r2 <- vapply(fits, function(f) {
    r <- suppressWarnings(summary(f)$r.squared)
    if (is.nan(r)) NA_real_ else r
  }, numeric(1))

  # Coefficients: from fxregime when it ran, else from the lm fits
  if (!is.null(reg)) {
    cm <- stats::coef(reg)
    if (is.null(dim(cm))) cm <- matrix(cm, nrow = 1, dimnames = list(NULL, names(cm)))
  } else {
    cm <- do.call(rbind, lapply(fits, function(f)
      c(stats::coef(f), `(Variance)` = mean(stats::resid(f)^2))))
  }
  if (nrow(cm) != k) stop("Coefficient rows (", nrow(cm), ") != number of regimes (", k, ")")

  regimes <- data.frame(
    regime = paste(format(dates[starts]), format(dates[ends]), sep = "--"),
    start  = dates[starts],
    end    = dates[ends],
    n_obs  = ends - starts + 1L,
    r2     = r2,
    cm, check.names = FALSE, row.names = NULL, stringsAsFactors = FALSE
  )

  # Weight of each currency on every date (for the weights plot)
  seg <- rep(seq_len(k), times = ends - starts + 1L)
  weights <- data.frame(
    date     = rep(dates, times = length(regs)),
    Currency = rep(regs, each = n),
    Weight   = as.vector(cm[seg, regs, drop = FALSE]),
    stringsAsFactors = FALSE
  )

  list(ccy = ccy, regressors = regs, regimes = regimes, level = level,
       weights = weights, break_dates = dates[bp], n_obs = n, note = note)
}

# ---- run --------------------------------------------------------------------
fx  <- read.csv("BRA_fx_data.csv")
res <- fit_country(
  fx,
  ccy        = "BRL",
  regressors = c("USD", "JPY", "EUR", "GBP"),
  h          = 26,
  breaks     = 10,
  ic         = "BIC",
  frequency  = "weekly"
)

print(res$break_dates)
print(res$regimes)
write.csv(res$regimes, "BRA_regimes.csv", row.names = FALSE)
